// ─── CONDITIONING SESSION ─────────────────────────────────────────────────────
// Fat burn / cardiovascular focus. HIIT-style circuits.
//
// A conditioning session is assembled from four pools rather than stored whole.
// The database used to hold exactly ONE prescribed session per equipment tier
// per energy level, so a user doing conditioning twice a week met the identical
// four exercises every time; rotating the order — which the engine now does —
// could only ever reorder them. Measured day-over-day overlap was 1.000.
//
// Composing the session instead of storing it is what makes the variety
// affordable. Eight work circuits, five finishers, four warm-ups and three
// cool-downs per cell combine into 480 distinct sessions, and because the four
// pool lengths share no common factor beyond one the same session does not come
// round again for 120 days.

